#include "../common/inventory_panel.h"
#include <cassert>
int main(){using namespace destinia;InventoryPanel p;p.items={{0,0,7,0,0,4,100},{0,1,9,2,1,18,800}};p.names={"ESPADA","ADAGA"};p.selectedPool=7;p.rebuild();assert(p.selected()==0);p.cycle(0,1,20);assert(p.view.size()==1&&p.selected()==0);p.cycle(0,1,20);assert(p.view.empty()&&!p.selected());p.reset();assert(p.selected()==0);p.focus=7;assert(p.key(9,20)==InventoryEvent::None&&p.selectedPool==9);assert(p.key(17,20)==InventoryEvent::Choose);assert(p.key(10,20)==InventoryEvent::Close);p.query.minPrice=1000;p.rebuild();assert(!p.selected());assert(p.key(17,20)==InventoryEvent::None);for(int n=2;n<8;n++)p.items.push_back({0,n,n+20,0,0,1,1});p.reset();p.selectedPool=7;p.page=0;p.hit(9,20);assert(p.page==1&&p.selectedPool==7);p.focus=7;assert(p.key(17,20)==InventoryEvent::None);p.move(1);assert(p.selected()&&*p.selected()==6);p.batchCount=3;p.batchProtected=2;p.batchEquipped=1;assert(p.hit(13,20)==InventoryEvent::BatchPreview);assert(p.batchPreview);assert(p.key(27,20)==InventoryEvent::BatchCancel&&!p.batchPreview);p.batchPreview=true;assert(p.hit(10,20)==InventoryEvent::BatchConfirm);assert(p.hit(11,20)==InventoryEvent::BatchCancel);for(int width:{400,800})for(int scale:{75,100,125}){int height=width==400?240:480;auto t=inventoryTransform(width,height,scale,true);auto r=inventoryPanelRect(width,height);auto b=t.rect(r.x,r.y,r.w,r.h);assert(b.x>=0&&b.y>=0&&b.x+b.w<=width&&b.y+b.h<=height);std::vector<uint8_t> bytes(width*height*2+32,0x5a);paintInventory(bytes.data()+16,width,height,scale,p,true,true);for(int i=0;i<16;i++)assert(bytes[i]==0x5a&&bytes[bytes.size()-1-i]==0x5a);auto point=t.point(r.x+10,r.y+30);assert(inventoryHit(point.first,point.second,width,height,scale,true)==0);auto batchButton=t.point(r.x+250,r.y+10);assert(inventoryHit(batchButton.first,batchButton.second,width,height,scale,true)==13);}}
